import urllib.request, json

# Try GitHub API to find the repo structure
url = 'https://api.github.com/repos/Yale-LILY/FOLIO/git/trees/main?recursive=1'
try:
    req = urllib.request.Request(url, headers={'User-Agent': 'Python'})
    resp = urllib.request.urlopen(req, timeout=15)
    tree = json.loads(resp.read().decode('utf-8'))
    for item in tree.get('tree', []):
        if 'data' in item['path'] or 'folio' in item['path'].lower() or item['path'].endswith('.jsonl') or item['path'].endswith('.json'):
            print(item['path'])
except Exception as e:
    print(f'main branch failed: {e}')
    # try master
    url2 = 'https://api.github.com/repos/Yale-LILY/FOLIO/git/trees/master?recursive=1'
    try:
        req = urllib.request.Request(url2, headers={'User-Agent': 'Python'})
        resp = urllib.request.urlopen(req, timeout=15)
        tree = json.loads(resp.read().decode('utf-8'))
        for item in tree.get('tree', []):
            if 'data' in item['path'] or 'folio' in item['path'].lower() or item['path'].endswith('.jsonl') or item['path'].endswith('.json'):
                print(item['path'])
    except Exception as e2:
        print(f'master also failed: {e2}')
